        }
        self.publish(&run, &publication, snapshot.content_changed).await.map_err(|error| invalid(&format!("sealed declaration run {run}; recover with declarations sync --resume {run}: {error}")))?;
        Ok(run)
    }

    async fn publish(
        &self,
        run: &IngestionKey,
        publication: &PreparedPublication,
        changed: bool,
    ) -> Result<(), EntityIngestionError> {
        let load = if changed {
            Some(self.storage.prepare_load(run).await?)
        } else {
            None
        };
        self.repository
            .publish_sync(publication, load.as_ref())
            .await?;
        Ok(())
    }
}

fn discovery_window(
    base: Option<&CompleteDeclarationSnapshot>,
    options: &DeclarationSyncOptions,
) -> Result<DiscoveryWindow, EntityIngestionError> {
    let previous_date = base.map_or(options.cutoff, |base| base.window.through);
    if options.cutoff < previous_date {
        return Err(invalid("cutoff cannot move committed coverage backwards"));
    }
    let window = DiscoveryWindow {
        from: previous_date
            .checked_sub_days(Days::new(options.overlap_days))
            .ok_or_else(|| invalid("discovery overlap exceeds date range"))?,
        through: options.cutoff,
    };
    Ok(window)
}

fn capture_scope(
    mode: DeclarationSyncMode,
    base: Option<&CompleteDeclarationSnapshot>,
    stored: &BTreeSet<MemberId>,
) -> Result<Vec<MemberId>, EntityIngestionError> {
    if stored.is_empty() {
        return Err(invalid("load members before capturing declarations"));
    }
    let scope = match (&mode, base) {
        (DeclarationSyncMode::Daily, Some(base)) => {
            if base.scope.iter().any(|member| !stored.contains(member)) {
                return Err(invalid(
                    "a member in the committed declaration scope is no longer stored",
                ));
            }
            base.scope.clone()
        }
        (DeclarationSyncMode::Daily, None) => unreachable!("daily baseline checked above"),
        (DeclarationSyncMode::Reconcile, _) => stored.iter().copied().collect(),
    };
    Ok(scope)
}

fn merge_record(
    records: &mut BTreeMap<
        crate::domain::models::declaration_ingestion::DeclarationId,
        OwnedDeclaration,
    >,
    record: OwnedDeclaration,
) -> Result<(), EntityIngestionError> {
    let id = record.declaration.id();
    if let Some(previous) = records.get(&id) {
        if previous.member != record.member {
            return Err(invalid("source declaration changed registrant"));
        }
        if previous.declaration.source_json() == record.declaration.source_json() {
            return Ok(());
        }
    }
    records.insert(id, record);
    Ok(())
}

/// Hashes source content without retrieval instants.
pub(crate) fn content_digest(
    records: &BTreeMap<
        crate::domain::models::declaration_ingestion::DeclarationId,
        OwnedDeclaration,
    >,
) -> Result<String, EntityIngestionError> {
    let content = records
        .iter()
        .map(|(id, record)| (id, record.member, record.declaration.source_json()))
        .collect::<Vec<_>>();
    Ok(digest(&serde_json::to_vec(&content).map_err(failure)?))
}
/// SHA-256 for persisted evidence.
pub(crate) fn digest(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}
fn invalid(message: &str) -> EntityIngestionError {
    EntityIngestionError::DataError(message.into())
}
fn failure(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(error.to_string())
}
//! Complete declaration evidence and its optimistic publication boundary.

use std::{collections::BTreeMap, path::PathBuf};

use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use super::{
    declaration_ingestion::{CapturedDeclaration, DeclarationId},
    parliament_member::MemberId,
};

/// Acquisition policy for a declaration run.
#[derive(Clone, Copy, Debug, Serialize, Deserialize)]
pub enum DeclarationSyncMode {
    /// Discover changed IDs within the committed scope.
    Daily,
    /// Capture the complete current stored-member cohort.
    Reconcile,
}

/// Inclusive source-date bounds. The source is date based, not a changefeed.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct DiscoveryWindow {
    /// First source date, including overlap.
    pub from: NaiveDate,
    /// Last source date, excluding the configured indexing lag.
    pub through: NaiveDate,
}

/// A complete source record and its checked registrant.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct OwnedDeclaration {
    /// Stored ownership prerequisite.
    pub member: MemberId,
    /// Complete unfiltered source record.
    pub declaration: CapturedDeclaration,
}

/// Source page evidence retained with a completed capture.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct DiscoveryReceipt {
    /// Query URL, including offset and bounds.
    pub url: String,
    /// SHA-256 of the response bytes.
    pub sha256: String,
    /// Reported source total.
    pub total: usize,
    /// IDs and registrants observed on this page.
    pub declarations: Vec<(DeclarationId, MemberId)>,
}

/// Immutable complete capture. A manifest exists only after every request and file succeeds.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CompleteDeclarationSnapshot {
    /// Format version.
    pub schema_version: u32,
    /// Stable run identity.
    pub run: Uuid,
    /// Publication head observed before acquisition.
    pub expected_revision: i64,
    /// Acquisition mode.
    pub mode: DeclarationSyncMode,
    /// Exact source endpoint and policy.
    pub source: String,
    /// Inclusive coverage bounds.
    pub window: DiscoveryWindow,
    /// Explicit cohort, including members with no declarations.
    pub scope: Vec<MemberId>,
    /// SHA-256 of the sorted member-ID cohort.
    pub scope_sha256: String,
    /// Stored members awaiting explicit historical declaration reconciliation.
    pub pending_members: Vec<MemberId>,
    /// Full evidence indexed by declaration ID.
    pub declarations: BTreeMap<DeclarationId, OwnedDeclaration>,
    /// Out-of-scope discoveries excluded from this capture.
    pub exclusions: BTreeMap<DeclarationId, MemberId>,
    /// Previously captured IDs omitted by a successful source request.
    pub omissions: Vec<DeclarationId>,
    /// All required source page receipts.
    pub receipts: Vec<DiscoveryReceipt>,
    /// Raw partition hashes, relative to the run directory.
    pub artifacts: BTreeMap<PathBuf, String>,
    /// Equality of complete source records, excluding retrieval times.
    pub content_sha256: String,
    /// Whether interpretation must run.
    pub content_changed: bool,
    /// Time at which all evidence was acquired.
    pub captured_at: DateTime<Utc>,
}

/// Database-selected committed capture, never inferred from filesystem recency.
#[derive(Clone, Debug)]
pub struct DeclarationSyncHead {
    /// Current publication revision.
    pub revision: i64,
    /// Sealed manifest selected by the database.
    pub manifest_path: PathBuf,
    /// Committed manifest digest.
    pub manifest_sha256: String,
}

/// Publication request checked under the declaration loader lock.
#[derive(Clone, Debug)]
pub struct PreparedPublication {
    /// Stable retry identity.
    pub run: Uuid,
    /// Expected committed revision.
    pub expected_revision: i64,
    /// Sealed immutable manifest.
    pub manifest_path: PathBuf,
    /// Digest binding the request to its evidence.
    pub manifest_sha256: String,
    /// Inclusive discovery checkpoint.
    pub coverage_date: NaiveDate,
}
"}

