//! Checked offset pagination and unfiltered declaration-ID hydration.
use super::ParliamentApiClient;
use crate::domain::{
    models::{
        declaration_ingestion::DeclarationId,
        declaration_sync::{DiscoveryReceipt, DiscoveryWindow, OwnedDeclaration},
        entity_ingestion::EntityIngestionError,
        parliament_member::MemberId,
    },
    repositories::declaration_sync::DeclarationSyncSource,
    services::declaration_sync::digest,
};
use chrono::Utc;
use serde::Deserialize;
use serde_json::Value;
use std::collections::BTreeMap;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Page {
    total_results: usize,
    items: Vec<Value>,
}

impl ParliamentApiClient {
    async fn sync_pages(
        &self,
        filters: Vec<(&str, String)>,
    ) -> Result<(Vec<Value>, Vec<DiscoveryReceipt>), EntityIngestionError> {
        let mut offset = 0;
        let mut expected_total = None;
        let mut items = Vec::new();
        let mut seen = BTreeMap::new();
        let mut receipts = Vec::new();
        loop {
            let mut query = filters.clone();
            query.extend([
                ("Type", "Commons".into()),
                ("ExcludeExpired", "false".into()),
                ("ExpandChildInterests", "false".into()),
                ("Skip", offset.to_string()),
                ("Take", self.batch_size.to_string()),
            ]);
            let mut endpoint = reqwest::Url::parse(&self.interests_url).map_err(error)?;
            endpoint.query_pairs_mut().extend_pairs(query);
            let request = self.client.get(endpoint).build().map_err(error)?;
            let url = request.url().to_string();
            let mut response = None;
            for attempt in 0..3 {
                match self
                    .client
                    .execute(
                        request
                            .try_clone()
                            .ok_or_else(|| error("request cannot be cloned"))?,
                    )
                    .await
                {
                    Ok(result) if result.status().is_success() => {
                        response = Some(result);
                        break;
                    }
                    Ok(result)
                        if (result.status().is_server_error()
                            || result.status().as_u16() == 429)
                            && attempt < 2 => {}
                    Ok(result) => {
                        return Err(error(format!(
                            "declaration request failed with {} at {url}",
                            result.status()
                        )));
                    }
                    Err(_) if attempt < 2 => {}
                    Err(failure) => return Err(error(failure)),
                }
                tokio::time::sleep(std::time::Duration::from_millis(100 * (attempt + 1))).await;
            }
            let bytes = response
                .ok_or_else(|| error("declaration retries exhausted"))?
                .bytes()
                .await
                .map_err(error)?;
            let page: Page = serde_json::from_slice(&bytes).map_err(error)?;
            if page.total_results > 1_000_000
                || expected_total.is_some_and(|total| total != page.total_results)
                || page.items.len() > usize::from(self.batch_size.get())
                || offset + page.items.len() > page.total_results
            {
                return Err(error(
                    "inconsistent declaration pagination total or page size",
                ));
            }
            expected_total = Some(page.total_results);
            if page.items.is_empty() && offset < page.total_results {
                return Err(error(
                    "declaration pagination truncated before its reported total",
                ));
            }
            let mut identities = Vec::new();
            for item in &page.items {
                let (id, owner) = identity(item)?;
                if seen.insert(id, owner).is_some() {
                    return Err(error(
                        "duplicate declaration ID across source pages; retry reconciliation",
                    ));
                }
                identities.push((id, owner));
            }
            offset += page.items.len();
            receipts.push(DiscoveryReceipt {
                url,
                sha256: digest(&bytes),
                total: page.total_results,
                declarations: identities,
            });
            items.extend(page.items);
            if offset == page.total_results {
                break;
            }
        }
        Ok((items, receipts))
    }
}

impl DeclarationSyncSource for ParliamentApiClient {
    fn policy(&self) -> String {
        format!(
            "{}; Commons; IncludeExpired; unfiltered hydration; offset pagination; UTC date windows v1",
            self.interests_url
        )
    }
    async fn discover(
        &self,
        window: &DiscoveryWindow,
    ) -> Result<(BTreeMap<DeclarationId, MemberId>, Vec<DiscoveryReceipt>), EntityIngestionError>
    {
        let mut identities = BTreeMap::new();
        let mut receipts = Vec::new();
        for (from, through) in [
            ("PublishedFrom", "PublishedTo"),
            ("UpdatedFrom", "UpdatedTo"),
        ] {
            let (items, pages) = self
                .sync_pages(vec![
                    (from, window.from.to_string()),
                    (through, window.through.to_string()),
                ])
                .await?;
            receipts.extend(pages);
            for item in items {
                let (id, owner) = identity(&item)?;
                if identities
                    .insert(id, owner)
                    .is_some_and(|previous| previous != owner)
                {
                    return Err(error("discovery has conflicting declaration registrants"));
                }
            }
        }
        Ok((identities, receipts))
    }
    async fn hydrate(
        &self,
        id: DeclarationId,
    ) -> Result<(Option<OwnedDeclaration>, Vec<DiscoveryReceipt>), EntityIngestionError> {
        let (mut items, receipts) = self
            .sync_pages(vec![("InterestIds", id.to_string())])
            .await?;
        if items.len() > 1 {
            return Err(error("ID hydration returned multiple declarations"));
        }
        let record = items.pop().map(decode).transpose()?;
        if record
            .as_ref()
            .is_some_and(|record| record.declaration.id() != id)
        {
            return Err(error("ID hydration returned the wrong declaration"));
        }
        Ok((record, receipts))
    }
    async fn capture_member(
        &self,
        member: MemberId,
    ) -> Result<(Vec<OwnedDeclaration>, Vec<DiscoveryReceipt>), EntityIngestionError> {
        let (items, receipts) = self
            .sync_pages(vec![("MemberId", member.to_string())])
            .await?;
        let records = items
            .into_iter()
            .map(decode)
            .collect::<Result<Vec<_>, _>>()?;
        if records.iter().any(|record| record.member != member) {
            return Err(error("member capture returned another registrant"));
        }
        Ok((records, receipts))
    }
}

fn identity(value: &Value) -> Result<(DeclarationId, MemberId), EntityIngestionError> {
    #[derive(Deserialize)]
    struct Identity {
        id: DeclarationId,
        registrant: Registrant,
    }
    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct Registrant {
        r#type: String,
        member_detail: Member,
    }
    #[derive(Deserialize)]
    struct Member {
        id: MemberId,
    }
    let identity: Identity = serde_json::from_value(value.clone()).map_err(error)?;
    if identity.registrant.r#type != "Member" {
        return Err(error("declaration registrant is not a member"));
    }
    Ok((identity.id, identity.registrant.member_detail.id))
}
fn decode(source: Value) -> Result<OwnedDeclaration, EntityIngestionError> {
    let (_, member) = identity(&source)?;
    let declaration = crate::outbound::declaration_source::decode_declaration(source, Utc::now())
        .map_err(error)?;
    Ok(OwnedDeclaration {
        member,
        declaration,
    })
}
fn error(error: impl std::fmt::Display) -> EntityIngestionError {
    EntityIngestionError::DataError(error.to_string())
}

//! Immutable capture artifacts and PostgreSQL publication metadata.
use super::{ExposedDataPipeline, ExposedDatabase, WeldrsFunderScorer};
use crate::domain::{
    models::{
        declaration_ingestion::DeclarationId,
        declaration_loading::DeclarationLoad,
        declaration_sync::{CompleteDeclarationSnapshot, DeclarationSyncHead, PreparedPublication},
        entity_ingestion::{DeclarationIngestionStage, EntityIngestionError, IngestionKey},
    },
    repositories::{
        declaration_loading::DeclarationLoadStorage,
        declaration_sync::{DeclarationSyncRepository, DeclarationSyncStorage},
        entity_ingestion::EntityIngestionStorage,
    },
    services::{
        declaration_cleaning::DeclarationCleanerService,
        declaration_resolution::DeclarationResolverService,
        declaration_sync::{content_digest, digest},
    },
};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
};

/// Artifact root and global resolution policy for declaration synchronization.
pub struct DeclarationSnapshotStore {
    root: PathBuf,
    candidate_budget: usize,
}
impl DeclarationSnapshotStore {
    /// Uses an absolute artifact root so committed references survive working-directory changes.
    ///
    /// # Errors
    /// Rejects an invalid root or zero candidate budget.
    pub fn new(root: &Path, candidate_budget: usize) -> Result<Self, EntityIngestionError> {
        if candidate_budget == 0 {
            return Err(error("candidate_budget must be positive"));
        }
        Ok(Self {
            root: std::path::absolute(root).map_err(error)?,
            candidate_budget,
        })
    }
}
impl DeclarationSyncStorage for DeclarationSnapshotStore {
    fn open_sealed_run(
        &self,
        run: &IngestionKey,
    ) -> Result<(CompleteDeclarationSnapshot, PreparedPublication), EntityIngestionError> {
        let path = self.root.join(run.to_string()).join("capture.json");
        let snapshot = self.read_snapshot(&path, None)?;
        let manifest_sha256 =
            fs::read_to_string(path.with_file_name("capture.sha256")).map_err(error)?;
        let publication = PreparedPublication {
            run: snapshot.run,
            expected_revision: snapshot.expected_revision,
            manifest_path: path,
            manifest_sha256,
            coverage_date: snapshot.window.through,
        };
        Ok((snapshot, publication))
    }
    fn read_snapshot(
        &self,
        path: &Path,
        expected_digest: Option<&str>,
    ) -> Result<CompleteDeclarationSnapshot, EntityIngestionError> {
        let bytes = fs::read(path).map_err(error)?;
        let marker = fs::read_to_string(path.with_file_name("capture.sha256")).map_err(error)?;
        if digest(&bytes) != marker
            || expected_digest.is_some_and(|expected| digest(&bytes) != expected)
        {
            return Err(error("committed capture manifest digest mismatch"));
        }
        let snapshot: CompleteDeclarationSnapshot =
            serde_json::from_slice(&bytes).map_err(error)?;
        if snapshot.schema_version != 1
            || snapshot.expected_revision < 0
            || snapshot.scope.is_empty()
            || snapshot.window.from > snapshot.window.through
            || snapshot
                .scope
                .iter()
                .copied()
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
                != snapshot.scope
            || snapshot.scope_sha256 != digest(&serde_json::to_vec(&snapshot.scope).map_err(error)?)
            || snapshot.content_sha256 != content_digest(&snapshot.declarations)?
        {
            return Err(error("invalid complete declaration manifest"));
        }
        let directory = path
            .parent()
            .ok_or_else(|| error("manifest has no parent"))?;
        let expected_paths = snapshot
            .scope
            .iter()
            .map(|member| PathBuf::from(format!("raw/declarations/{member}.parquet")))
            .collect::<BTreeSet<_>>();
        if snapshot.artifacts.keys().cloned().collect::<BTreeSet<_>>() != expected_paths {
            return Err(error("manifest does not cover every cohort partition"));
        }
        for (relative, expected) in &snapshot.artifacts {
            if digest(&fs::read(directory.join(relative)).map_err(error)?) != *expected {
                return Err(error("raw declaration artifact digest mismatch"));
            }
            let partition = super::declaration_cleaning::read_partition(&directory.join(relative))?;
            let expected_records = snapshot
                .declarations
                .values()
                .filter(|record| record.member == partition.member)
                .count();
            if partition.declarations.len() != expected_records {
                return Err(error("partition differs from sealed declaration set"));
            }
            for evidence in partition.declarations {
                let actual = evidence.declaration();
                let expected = snapshot
                    .declarations
                    .get(&actual.id())
                    .ok_or_else(|| error("unexpected declaration in raw partition"))?;
                if expected.member != partition.member
                    || actual.source_json() != expected.declaration.source_json()
                    || actual.fetched_at() != expected.declaration.fetched_at()
                {
                    return Err(error("raw partition disagrees with capture manifest"));
                }
            }
        }
        for (id, record) in &snapshot.declarations {
            if *id != record.declaration.id() || !snapshot.scope.contains(&record.member) {
                return Err(error("manifest contains invalid declaration ownership"));
            }
        }
        Ok(snapshot)
    }
    async fn seal_snapshot(
        &self,
        mut snapshot: CompleteDeclarationSnapshot,
    ) -> Result<PreparedPublication, EntityIngestionError> {
        fs::create_dir_all(&self.root).map_err(error)?;
        let key = IngestionKey::new(snapshot.run);
        let staging_root = self.root.join(format!(".capture-{}", snapshot.run));
        fs::create_dir(&staging_root).map_err(error)?;
        let storage = ExposedDataPipeline::new_with_ingestion_key(&staging_root, key.clone())?;
        let staged_run = staging_root.join(key.to_string());
        for member in &snapshot.scope {
            let records = snapshot
                .declarations
                .values()
                .filter(|record| record.member == *member)
                .map(|record| record.declaration.clone())
                .collect::<Vec<_>>();
            storage.write_raw_declarations(*member, &records).await?;
            let relative = PathBuf::from(format!("raw/declarations/{member}.parquet"));
            snapshot.artifacts.insert(
                relative.clone(),
                digest(&fs::read(staged_run.join(relative)).map_err(error)?),
            );
        }
        let bytes = serde_json::to_vec_pretty(&snapshot).map_err(error)?;
        fs::write(staged_run.join("capture.json"), &bytes).map_err(error)?;
        fs::write(staged_run.join("capture.sha256"), digest(&bytes)).map_err(error)?;
        sync_tree(&staged_run)?;
        let destination = self.root.join(key.to_string());
        if destination.exists() {
            return Err(error("capture run already exists"));
        }
        fs::rename(&staged_run, &destination).map_err(error)?;
        fs::File::open(&self.root)
            .and_then(|file| file.sync_all())
            .map_err(error)?;
        fs::remove_dir(staging_root).map_err(error)?;
        let manifest_path = destination.join("capture.json");
        self.read_snapshot(&manifest_path, Some(&digest(&bytes)))?;
        Ok(PreparedPublication {
            run: snapshot.run,
            expected_revision: snapshot.expected_revision,
            manifest_path,
            manifest_sha256: digest(&bytes),
            coverage_date: snapshot.window.through,
        })
    }
    async fn prepare_load(
        &self,
        run: &IngestionKey,
    ) -> Result<DeclarationLoad, EntityIngestionError> {
        let directory = self.root.join(run.to_string());
        self.read_snapshot(&directory.join("capture.json"), None)?;
        let storage = ExposedDataPipeline::open_existing_declarations(&self.root, run.clone())?;
        for stage in [
            DeclarationIngestionStage::Clean,
            DeclarationIngestionStage::Resolve,
        ] {
            let name = match stage {
                DeclarationIngestionStage::Clean => "cleaned",
                DeclarationIngestionStage::Resolve => "resolved",
                DeclarationIngestionStage::Fetch
                | DeclarationIngestionStage::Load
                | DeclarationIngestionStage::Sync
                | DeclarationIngestionStage::Reconcile => unreachable!("derived stages only"),
            };
            let output = directory.join(name).join("declarations");
            let receipt = directory.join(format!("{name}-sha256.json"));
            if output.exists() && receipt.exists() {
                validate_hashes(&directory, &receipt, &output)?;
            } else {
                if output.exists() {
                    fs::remove_dir_all(&output).map_err(error)?;
                }
                match stage {
                    DeclarationIngestionStage::Clean => {
                        DeclarationCleanerService::new(storage.clone())
                            .clean_declarations()
                            .await?;
                    }
                    DeclarationIngestionStage::Resolve => {
                        DeclarationResolverService::new(
                            storage.clone(),
                            WeldrsFunderScorer::new()?,
                            self.candidate_budget,
                        )
                        .resolve_declarations()
                        .await?;
                    }
                    DeclarationIngestionStage::Fetch
                    | DeclarationIngestionStage::Load
                    | DeclarationIngestionStage::Sync
                    | DeclarationIngestionStage::Reconcile => unreachable!("derived stages only"),
                }
                sync_tree(&output)?;
                let hashes = directory_hashes(&directory, &output)?;
                durable_json(&receipt, &hashes)?;
            }
        }
        self.read_snapshot(&directory.join("capture.json"), None)?;
        storage.read_declaration_load().await
    }
}

impl DeclarationSyncRepository for ExposedDatabase {
    async fn sync_head(&self) -> Result<Option<DeclarationSyncHead>, EntityIngestionError> {
        let row = sqlx::query!("SELECT run.revision, run.manifest_path, run.manifest_sha256 FROM exposed.declaration_sync_head head JOIN exposed.declaration_sync_runs run USING (ingestion_key) WHERE head.singleton").fetch_optional(self.pool()).await.map_err(error)?;
        Ok(row.map(|row| DeclarationSyncHead {
            revision: row.revision,
            manifest_path: row.manifest_path.into(),
            manifest_sha256: row.manifest_sha256,
        }))
    }
    async fn projected_declaration_ids(&self) -> Result<Vec<DeclarationId>, EntityIngestionError> {
        sqlx::query!("SELECT source_declaration_id FROM exposed.declarations WHERE source_declaration_id IS NOT NULL").fetch_all(self.pool()).await.map_err(error)?.into_iter().map(|row| DeclarationId::new(u32::try_from(row.source_declaration_id).map_err(error)?)).collect()
    }
    async fn publish_sync(
        &self,
        publication: &PreparedPublication,
        load: Option<&DeclarationLoad>,
    ) -> Result<bool, EntityIngestionError> {
        self.publish_declaration_sync(publication, load).await
    }
}

fn directory_hashes(
    root: &Path,
    directory: &Path,
) -> Result<BTreeMap<PathBuf, String>, EntityIngestionError> {
    let mut result = BTreeMap::new();
    for entry in fs::read_dir(directory).map_err(error)? {
